import {products,suppliers,stores,CHECKED,SOURCES} from './data.js';
import {validBarcode,miles,cleanBasket} from './logic.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let state={route:location.hash.slice(1)||'discover',category:'All meat',search:'',filter:'all',saved:read('ff-saved',[]),basket:read('ff-basket',{}),outdoor:read('ff-outdoor',true),onlySaved:false,storeType:'All',origin:null};
state.basket=cleanBasket(state.basket,products.map(p=>p.id));
state.saved=Array.isArray(state.saved)?state.saved.filter(id=>products.some(p=>p.id===id)):[];
if(typeof state.outdoor!=='boolean')state.outdoor=true;
const nav=[['discover','compass','Discover'],['scan','scan-barcode','Scan & check'],['nearby','map-pin','Nearby'],['suppliers','tractor','Suppliers'],['basket','shopping-basket','My basket']];
const speciesIcon=s=>s==='Chicken'?'drumstick':s==='Pork'?'pig':'beef';
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.7}})}
function count(){return Object.values(state.basket).reduce((a,b)=>a+b,0)}
function navigation(){const links=nav.map(([id,i,label])=>`<a class="nav-link ${state.route===id?'active':''}" href="#${id}" ${state.route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='basket'&&count()?`<span class="nav-badge">${count()}</span>`:''}</a>`).join('');$('#desktop-nav').innerHTML=links;$('#mobile-nav').innerHTML=links;$('#breadcrumb').textContent=nav.find(n=>n[0]===state.route)?.[2]||'Your shopping companion'}
function productCard(p){return `<article class="product-card"><div class="card-top"><span class="species-icon">${icon(speciesIcon(p.species))}</span><button class="icon-button ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${icon('bookmark')}</button></div><div class="retailer">${esc(p.retailer)} · ${p.species}</div><button class="product-title" data-action="product" data-id="${p.id}">${esc(p.name)}</button><div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${!p.outdoor?'<span class="tag amber">Indoor system</span>':''}</div><div class="product-evidence">${icon(p.directory?'badge-check':'file-check-2')}${p.directory?'Certifier directory matched':'Product sourcing listed'}</div><div class="card-bottom"><button class="text-button" data-action="product" data-id="${p.id}">View sourcing ${icon('arrow-up-right')}</button><button class="btn small" data-action="add" data-id="${p.id}">${icon('plus')}Add to list</button></div></article>`}
function filtered(){return products.filter(p=>(state.category==='All meat'||p.species===state.category)&&(!state.outdoor||p.outdoor)&&(!state.onlySaved||state.saved.includes(p.id))&&(state.filter==='all'||(state.filter==='organic'&&p.tags.includes('Organic'))||(state.filter==='direct'&&p.farm))&&`${p.name} ${p.retailer} ${p.tags.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()))}
function results(){const items=filtered();$('#results-count').textContent=`${items.length} sourcing candidates`;$('#products-grid').innerHTML=items.length?items.map(productCard).join(''):`<div class="empty">${icon('search')}<h2>No matching cuts yet</h2><p>Try another meat, supplier or filter. Our first catalogue is deliberately small.</p><button class="btn" data-action="reset-filters">Clear filters</button></div>`;icons()}
function discover(){return `<section class="page-heading"><div><p class="eyebrow">THE EDINBURGH EDIT</p><h1>Your next good shop.</h1><p class="subheading">Beef, lamb, pork & chicken. Sourcing you can inspect.</p></div><a class="btn" href="#scan">${icon('scan-line')}Check a product</a></section><section class="feature"><div class="feature-copy"><p class="eyebrow">CLOSER TO THE SOURCE</p><h2>A better place<br>to begin.</h2><p>Meet the farms and suppliers behind your next meat shop.</p><a class="text-button" href="#suppliers">Explore the shortlist ${icon('arrow-up-right')}</a></div><div class="feature-image"><img src="./assets/pasture.jpg" alt="Illustrative Scottish pasture with grazing cattle" width="1942" height="809"><span class="image-credit">Illustrative landscape</span></div></section><div class="search-row"><label class="search-field">${icon('search')}<input id="product-search" aria-label="Search cuts, farms or shops" placeholder="Search cuts, farms or shops…" value="${esc(state.search)}" type="search"></label><select id="source-filter" aria-label="Filter sourcing"><option value="all">All sources</option><option value="organic">Organic listed</option><option value="direct">Named farms</option></select><button class="btn ${state.onlySaved?'primary':''}" data-action="saved-only" aria-pressed="${state.onlySaved}">${icon('bookmark')}Saved</button></div><div class="category-tabs" aria-label="Meat categories">${['All meat','Beef','Lamb','Pork','Chicken'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div class="catalogue-heading"><h2>${state.onlySaved?'Your saved cuts':'Worth a closer look'}</h2><span class="result-count" id="results-count"></span></div><div class="products-grid" id="products-grid"></div><p class="footer-note">${icon('info')}Sourcing candidates, not blanket approvals. Research checked 22 September 2026. Check the current pack; local stock is unconfirmed.</p>`}
function render(){
 navigation();
 const views={discover,nearby:nearbyView,suppliers:suppliersView,basket:basketView,scan:scanView};
 $('#main').innerHTML=(views[state.route]||discover)();
 if(state.route==='discover'){
   $('#source-filter').value=state.filter;results();
   $('#product-search').addEventListener('input',e=>{state.search=e.target.value;results()});
   $('#source-filter').addEventListener('change',e=>{state.filter=e.target.value;results()});
 }
 if(state.route==='nearby')$('#store-type').addEventListener('change',e=>{state.storeType=e.target.value;render()});
 if(state.route==='scan')$('#barcode-form').addEventListener('submit',e=>{e.preventDefault();barcodeResult($('#barcode-input').value.trim())});
 icons();
}

function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function persist(){try{localStorage.setItem('ff-saved',JSON.stringify(state.saved));localStorage.setItem('ff-basket',JSON.stringify(state.basket));localStorage.setItem('ff-outdoor',JSON.stringify(state.outdoor));return true}catch{toast('Storage is unavailable. Keep this tab open to retain your list.');return false}}
function add(id){if(!products.some(p=>p.id===id))throw new Error('Unknown product');state.basket[id]=Math.min(99,(state.basket[id]||0)+1);persist();navigation();if(state.route==='basket')render();icons();toast('Added to your shopping list')}
function dialog(title,body,actions=''){ $('#dialog-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">FIELDFARE</p><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();icons()}
function productDetail(id){const p=products.find(p=>p.id===id);if(!p)return;dialog(esc(p.name),`<p>${esc(p.retailer)} · ${p.species}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p>${esc(p.note)}</p><div class="note-box"><b>${!p.outdoor&&state.outdoor?'Below your outdoor-access standard':'Sourcing candidate — check the current pack'}</b><p>Evidence describes sourcing, not an animal’s entire experience. Current certificate scope and batch linkage still need checking.</p></div><div class="check-row"><b>Production claims</b><span>Documented on product page</span></div><div class="check-row"><b>Named farm</b><span>${p.farm?esc(p.farm):'Not established'}</span></div><div class="check-row"><b>Certifier directory</b><span>${p.directory?'Farm directory match':'Not independently matched'}</span></div><div class="check-row"><b>Current product scope / batch</b><span>Check before buying</span></div><a class="source-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Read supplier / retailer evidence</a>${p.directory?`<a class="source-link" href="${SOURCES.pfl}" target="_blank" rel="noopener noreferrer">${icon('file-text')}Pasture for Life directory</a>`:''}<p class="method-note">Evidence reviewed ${p.checked}. This catalogue does not show live price or branch stock.</p>`,`<a class="btn" href="${p.url}" target="_blank" rel="noopener noreferrer">Visit supplier ${icon('arrow-up-right')}</a><button class="btn primary" data-action="add" data-id="${p.id}">${icon('plus')}Add to list</button>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='close')$('#detail-dialog').close();if(a==='product')productDetail(id);if(a==='add')add(id);if(a==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render()}if(a==='category'){state.category=el.dataset.category;render()}if(a==='saved-only'){state.onlySaved=!state.onlySaved;render()}if(a==='reset-filters'){state.category='All meat';state.search='';state.filter='all';state.onlySaved=false;render()}});
window.addEventListener('hashchange',()=>{stopCamera();if($('#detail-dialog').open)$('#detail-dialog').close();state.route=location.hash.slice(1)||'discover';if(!nav.some(n=>n[0]===state.route))state.route='discover';render();window.scrollTo(0,0)});
function heading(eyebrow,title,subtitle,action=''){return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subheading">${subtitle}</p></div>${action}</section>`}
function nearbyView(){let list=stores.filter(s=>state.storeType==='All'||s.type===state.storeType);if(state.origin)list=[...list].sort((a,b)=>(coordinates[a.postcode]?miles(state.origin,coordinates[a.postcode]):Infinity)-(coordinates[b.postcode]?miles(state.origin,coordinates[b.postcode]):Infinity));return `${heading('EDINBURGH & AROUND','Find your next stop.','Real shops and collection points. Check stock before setting off.',`<button class="btn" data-action="location">${icon('locate-fixed')}Set starting point</button>`)}<div class="search-row"><button class="btn" data-action="location">${icon('map-pin')}${state.origin?esc(state.origin.label):'Set postcode or use location'}</button><select id="store-type" aria-label="Type of shop">${['All','Supermarket','Farm','Butcher'].map(t=>`<option ${t===state.storeType?'selected':''}>${t}</option>`).join('')}</select>${state.origin?'<button class="text-button" data-action="clear-location">Clear location</button>':''}</div>${state.origin?'<p class="method-note">Approximate straight-line distances to postcode centres. These are not driving or walking distances.</p>':''}<div class="list-stack">${list.map(s=>{const n=products.filter(p=>p.retailer===s.retailer&&(!state.outdoor||p.outdoor)).length;return `<article class="location-card"><span class="species-icon">${icon(s.type==='Farm'?'tractor':s.type==='Butcher'?'store':'shopping-bag')}</span><div class="location-info"><div class="small-caps">${s.type}${state.origin&&coordinates[s.postcode]?` · ${miles(state.origin,coordinates[s.postcode]).toFixed(1)} miles approx.`:''}</div><h3>${esc(s.name)}</h3><p>${esc(s.address)} · ${s.postcode}</p><p>${esc(s.note)}${n?` · ${n} catalogue ${n===1?'candidate':'candidates'}`:''}</p></div><div class="store-actions"><a class="btn small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.name+' '+s.address+' '+s.postcode)}" target="_blank" rel="noopener noreferrer">${icon('navigation')}Directions</a><a class="btn small" href="${s.url}" target="_blank" rel="noopener noreferrer">Store info ${icon('arrow-up-right')}</a></div></article>`}).join('')}</div><p class="footer-note">${icon('info')}Catalogue counts describe the retailer’s listed products, not stock at this branch. Coordinates: Postcodes.io / ONS postcode data.</p>`}
function suppliersView(){return `${heading('KNOW WHO’S BEHIND IT','Closer to the farm.','An Edinburgh shortlist, with each supplier’s evidence and limits made clear.')}<div class="supplier-grid">${suppliers.map(s=>`<article class="supplier-card"><div class="card-top"><span class="supplier-initials">${s.initials}</span><span class="tag">${s.type}</span></div><div class="small-caps">${esc(s.area)}</div><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="product-evidence">${icon(s.evidence.includes('match')?'badge-check':'file-text')}${s.evidence}</div><div class="card-bottom"><span class="result-count">${esc(s.access)}</span><button class="text-button" data-action="supplier" data-id="${s.id}">View profile ${icon('arrow-up-right')}</button></div></article>`).join('')}</div><p class="footer-note">${icon('info')}A certified farm can also sell bought-in meat. Always match the evidence to your chosen product.</p>`}
function supplierDetail(id){const s=suppliers.find(s=>s.id===id);if(!s)return;dialog(esc(s.name),`<p>${esc(s.area)} · ${s.type}</p><p>${esc(s.desc)}</p><div class="note-box"><b>${s.evidence}</b><p>${esc(s.note)}</p></div><div class="check-row"><b>How to shop</b><span>${esc(s.access)}</span></div><a class="source-link" href="${s.source}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Read sourcing / collection evidence</a>${s.products.length?`<h3 style="margin-top:24px">In your catalogue</h3>${s.products.map(id=>{const p=products.find(p=>p.id===id);return `<button class="btn wide" data-action="product" data-id="${id}">${esc(p.name)} ${icon('arrow-right')}</button>`}).join('')}`:'<p class="method-note">No product-level candidates have been added for this supplier yet. Ask for the exact farm, production system and certification of the cut you want.</p>'}`,`<a class="btn primary" href="${s.url}" target="_blank" rel="noopener noreferrer">Visit supplier ${icon('arrow-up-right')}</a>`)}
function basketView(){const items=products.filter(p=>state.basket[p.id]);if(!items.length)return `${heading('YOUR NEXT SHOP','A considered basket.','Keep your chosen cuts together, ready for your next shop.')}<div class="empty">${icon('shopping-basket')}<h2>Make a good start.</h2><p>Add meat from the catalogue to build your shopping list. Your choices stay on this device.</p><a class="btn primary" href="#discover">Explore the catalogue ${icon('arrow-right')}</a></div>`;const shops=[...new Set(items.map(p=>p.retailer))];return `${heading('YOUR NEXT SHOP','A considered basket.','A shopping list, not an order. Check the sourcing and current pack before buying.',`<button class="btn" data-action="export">${icon('download')}Export list</button>`)}<div class="basket-layout"><div class="list-stack">${items.map(p=>`<article class="basket-item"><span class="species-icon">${icon(speciesIcon(p.species))}</span><div class="item-info"><p>${esc(p.retailer)}</p><h3><button class="text-button" data-action="product" data-id="${p.id}">${esc(p.name)}</button></h3><span class="tag ${!p.outdoor&&state.outdoor?'amber':''}">${!p.outdoor&&state.outdoor?'Outside your outdoor standard':'Review current pack'}</span></div><div class="quantity"><button data-action="decrease" data-id="${p.id}" aria-label="Decrease quantity of ${esc(p.name)}">${icon('minus')}</button><span aria-label="Quantity">${state.basket[p.id]}</span><button data-action="increase" data-id="${p.id}" aria-label="Increase quantity of ${esc(p.name)}">${icon('plus')}</button></div><button class="icon-button" data-action="remove" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">${icon('trash-2')}</button></article>`).join('')}</div><aside class="summary-panel"><h3>Your shop, at a glance.</h3><div class="summary-row"><span>Items on your list</span><b>${count()}</b></div><div class="summary-row"><span>Suppliers / retailers</span><b>${shops.length}</b></div><p style="margin-top:18px">Every item is a sourcing candidate. The list does not confirm stock, a purchase, or a welfare audit.</p><button class="btn primary wide" data-action="basket-stores">${icon('map-pin')}Find buying options</button><button class="btn wide" data-action="export">${icon('download')}Export your list</button></aside></div>`}
function basketStores(){const items=products.filter(p=>state.basket[p.id]);const names=[...new Set(items.map(p=>p.retailer))];dialog('Where to buy your list',`${names.map(name=>{const p=items.find(p=>p.retailer===name),n=items.filter(p=>p.retailer===name).length;return `<div class="check-row"><b>${esc(name)}<br><span>${n} different ${n===1?'item':'items'}</span></b><a class="text-button" href="${p.url}" target="_blank" rel="noopener noreferrer">Check / preorder ${icon('arrow-up-right')}</a></div>`}).join('')}<p class="method-note">Links open the relevant supplier or product page. No retailer inventory or checkout is connected.</p>`,`<a href="#nearby" class="btn primary">See Edinburgh shops ${icon('map-pin')}</a>`)}
function scanView(){return `${heading('IN THE AISLE','Know what you’re holding.','Read a barcode, then check the source. A barcode alone cannot verify welfare.')}<div class="scan-layout"><section class="scan-surface">${icon('scan-barcode')}<h2>A closer look, in seconds.</h2><p>Use your camera or a pack photo to read the product’s barcode.</p><button class="btn" data-action="camera">${icon('camera')}Open scanner</button><button class="text-button" style="color:#dae5cb;margin-top:18px" data-action="photo">${icon('image')}Read a barcode photo</button><input id="barcode-photo" type="file" accept="image/*" hidden></section><section class="scan-help"><h2>Have the number instead?</h2><p>Enter the digits printed below the barcode.</p><form id="barcode-form"><input id="barcode-input" class="field" inputmode="numeric" autocomplete="off" placeholder="EAN / UPC number" aria-label="Barcode number" maxlength="14" required><button class="btn primary" type="submit">Check</button></form><div class="mini-step"><span>1</span><div><b>Identify the product</b><p>Read the code without guessing a farm or source.</p></div></div><div class="mini-step"><span>2</span><div><b>Check the evidence</b><p>This first catalogue has no independently verified barcode links yet. Unmatched codes stay unverified.</p></div></div><div class="mini-step"><span>3</span><div><b>Find a better-documented cut</b><p>Search the catalogue for the meat and retailer on your pack.</p></div></div></section></div>`}
function barcodeResult(code){stopCamera();if(!validBarcode(code)){dialog('Check those digits',`<p>The barcode should contain 8, 12, 13 or 14 digits and a valid check digit. Try entering it again or use a clearer photo.</p>`,`<button class="btn primary" data-action="close">Try again</button>`);return}dialog('No reviewed barcode match',`<p class="eyebrow">BARCODE ${esc(code)}</p><div class="note-box"><b>Sourcing not verified</b><p>This barcode is not linked to a reviewed Fieldfare product. It has not been scored or approved.</p></div><p>You can look up the product on Open Food Facts, then search this catalogue by meat or retailer. Third-party product data is not welfare evidence.</p><a class="source-link" href="https://world.openfoodfacts.org/product/${code}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Look up product identity on Open Food Facts</a>`,`<a class="btn primary" href="#discover">Search meat catalogue ${icon('search')}</a>`)}
let cameraControls=null,cameraCancelled=false,scannerPromise=null;
function loadScanner(){if(window.ZXingBrowser)return Promise.resolve(window.ZXingBrowser);if(!scannerPromise)scannerPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./assets/zxing.min.js';s.onload=()=>resolve(window.ZXingBrowser);s.onerror=()=>{scannerPromise=null;s.remove();reject(new Error('Scanner could not load'))};document.head.appendChild(s)});return scannerPromise}
function stopCamera(){cameraCancelled=true;cameraControls?.stop();cameraControls=null;const video=$('#camera-video');video?.srcObject?.getTracks().forEach(t=>t.stop());if(video)video.srcObject=null}
async function startCamera(){cameraCancelled=false;dialog('Scan the pack',`<video id="camera-video" class="camera-video" muted playsinline></video><p id="camera-status" role="status">Starting camera…</p><p>Point at the barcode in good light. Camera images stay on your device.</p>`);try{const zxing=await loadScanner();if(cameraCancelled)return;const reader=new zxing.BrowserMultiFormatReader();const controls=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}},audio:false},$('#camera-video'),(result)=>{if(result&&!cameraCancelled)barcodeResult(result.getText())});if(cameraCancelled){controls.stop();return}cameraControls=controls;$('#camera-status').textContent='Camera ready — keep the barcode steady.'}catch(error){if(cameraCancelled)return;$('#camera-status').textContent='Camera unavailable. Allow camera access in your browser, or enter the number / choose a photo.';$('#camera-status').className='error'}}
async function scanPhoto(file){if(!file)return;dialog('Reading your photo',`<p role="status">Looking for a barcode. The image stays on your device.</p>`);const url=URL.createObjectURL(file);try{const z=await loadScanner();const result=await new z.BrowserMultiFormatReader().decodeFromImageUrl(url);barcodeResult(result.getText())}catch{dialog('No barcode found',`<p>Try a close, sharp photo of the complete barcode, or enter the printed digits. Nothing has been uploaded.</p>`,`<button class="btn primary" data-action="close">Try another way</button>`)}finally{URL.revokeObjectURL(url)}}
let coordinates={};
fetch('./locations.json').then(r=>r.json()).then(data=>{coordinates=data;if(state.route==='nearby')render()}).catch(()=>{});
function locationDialog(){dialog('Your starting point',`<p>Choose a postcode for approximate distances, or use your current location. This is only used for this session.</p><form id="postcode-form"><label for="postcode-input">UK postcode</label><input class="field" id="postcode-input" autocomplete="postal-code" placeholder="For example, EH1 3RZ" maxlength="10" required><p style="font-size:12px;margin:9px 0">A postcode you submit is sent to Postcodes.io to find its centre.</p><button class="btn primary" type="submit">Find nearby shops</button></form><p id="location-error" role="status"></p><div class="check-row"><b>Or use your device</b><button class="text-button" data-action="geolocate">${icon('locate-fixed')}Use my location</button></div><p class="method-note">Device coordinates stay in this tab. There is no background tracking.</p>`);$('#postcode-form').addEventListener('submit',async e=>{e.preventDefault();const code=$('#postcode-input').value.trim();const error=$('#location-error');if(!/^[A-Za-z]{1,2}\d[A-Za-z\d]?\s*\d[A-Za-z]{2}$/.test(code)){error.textContent='Enter a complete UK postcode.';error.className='error';return}const button=e.target.querySelector('button');button.disabled=true;error.textContent='Looking up your postcode…';try{const r=await fetch('https://api.postcodes.io/postcodes/'+encodeURIComponent(code),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const {result}=await r.json();setOrigin({latitude:result.latitude,longitude:result.longitude,label:result.postcode})}catch{error.textContent='Postcode not found or connection unavailable. Try again, or browse the Edinburgh list.';error.className='error'}finally{button.disabled=false}})}
function setOrigin(origin){state.origin=origin;$('#location-label').textContent=origin.label;$('#detail-dialog').close();if(state.route!=='nearby')location.hash='nearby';else render()}
function geolocate(){const status=$('#location-error');if(!navigator.geolocation){status.textContent='Location is not supported here. Use a postcode instead.';return}status.textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(p=>setOrigin({latitude:p.coords.latitude,longitude:p.coords.longitude,label:'Current location'}),()=>{status.textContent='Location unavailable. Use a postcode or browse without distances.';status.className='error'},{enableHighAccuracy:false,timeout:10000,maximumAge:120000})}
function standardsDialog(){dialog('Your sourcing standards',`<p>Focus on properly farmed meat, with visible evidence for the product you actually buy.</p><label class="toggle-row"><input type="checkbox" id="outdoor-toggle" ${state.outdoor?'checked':''}><div>Require outdoor-access evidence<span>Hide the catalogue’s known indoor chicken systems. A listed outdoor claim still needs product-level verification.</span></div></label><div class="check-row"><b>Recommendations</b><span>Meat only</span></div><div class="check-row"><b>Unknown sourcing</b><span>Never automatically approved</span></div><div class="check-row"><b>Preferred area</b><span>Edinburgh and around</span></div><p class="method-note">Certification helps assess farming standards. It cannot prove that an individual animal never suffered. Winter shelter is not automatically poor welfare.</p>`,`<button class="btn primary" data-action="save-standards">Save standards</button>`)}
function aboutDialog(){dialog('Evidence, without guesswork',`<p>Fieldfare starts with a small, researched catalogue. Each product links to its original retailer, supplier or certifier source.</p><div class="check-row"><b>Product listing</b><span>The seller describes the sourcing</span></div><div class="check-row"><b>Directory match</b><span>The farm appears in a certifier’s directory</span></div><div class="check-row"><b>Current product / batch</b><span>Still requires a purchase-time check</span></div><p style="margin-top:20px">These are evidence levels, not a numerical measure of animal suffering. We do not give a retailer’s entire range the status of its best product.</p><p>Research checked 22 September 2026. Availability and prices are not live. The pasture image is an original illustrative image, not a photograph of a listed supplier.</p><a class="source-link" href="${SOURCES.pfl}" target="_blank" rel="noopener noreferrer">Pasture for Life directory ${icon('external-link')}</a><a class="source-link" href="${SOURCES.organic}" target="_blank" rel="noopener noreferrer">Approved UK organic control bodies ${icon('external-link')}</a><p class="method-note">No advertising trackers or account required for your list. Saved products, your basket and preferences stay in this browser; the hosting service may require sign-in to open this private app. Directions and supplier links open external services.</p>`)}
let installPrompt=null,swRegistration=null,offlineReady=false;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Fieldfare is installed')});
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}dialog('Fieldfare, on your home screen',`<p>Install the app for quick access and a quieter, full-screen experience.</p><div class="check-row"><b>iPhone / iPad · Safari</b><span>Share → Add to Home Screen</span></div><div class="check-row"><b>Android · Chrome</b><span>Browser menu → Install app</span></div><div class="check-row"><b>Desktop · Chrome or Edge</b><span>Use the install icon in the address bar</span></div><p class="method-note">If you are viewing this inside another app, open the site in your regular browser first. The catalogue and your list work offline after the first complete visit; supplier links and postcode lookup need a connection.</p>`)}
function exportData(){const data={app:'Fieldfare',version:1,exported:new Date().toISOString(),saved:state.saved,basket:products.filter(p=>state.basket[p.id]).map(p=>({id:p.id,name:p.name,supplier:p.retailer,quantity:state.basket[p.id],source:p.url})),preferences:{outdoorAccess:state.outdoor,meatOnly:true}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldfare-shopping-list.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your list has been exported')}
function settingsDialog(){dialog('Make yourself at home',`<div class="check-row"><b>Storage</b><span>This device only</span></div><div class="check-row"><b>Offline catalogue</b><span id="offline-readiness">${offlineReady?'Ready on this device':'Preparing — connect and revisit'}</span></div><div class="check-row"><b>Research date</b><span>22 September 2026</span></div><p style="margin-top:18px">Your basket and saved items are stored in this browser. They are not synced to other devices. Clearing browser data will remove them.</p><div class="two-buttons"><button class="btn" data-action="install">${icon('download')}Install app</button><button class="btn" data-action="export">Export list</button><button class="btn" data-action="standards">Your standards</button></div>${swRegistration?.waiting?'<button class="btn primary wide" data-action="update-app">Update available — refresh app</button>':''}<p class="method-note">App assets are cached for offline use. External stock checks, maps and supplier websites need an internet connection.</p><button class="text-button" style="color:var(--red)" data-action="reset-dialog">Clear saved data on this device</button>`)}
function checkOffline(){const worker=navigator.serviceWorker?.controller||swRegistration?.active;if(!worker)return;const channel=new MessageChannel();channel.port1.onmessage=e=>{offlineReady=!!e.data.ready;if($('#offline-readiness'))$('#offline-readiness').textContent=offlineReady?'Ready on this device':'Still preparing';channel.port1.close()};worker.postMessage({type:'CACHE_STATUS'},[channel.port2])}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{swRegistration=reg;navigator.serviceWorker.ready.then(()=>checkOffline());reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting)toast('An app update is ready. Open settings to refresh.')})})}).catch(()=>{offlineReady=false});
navigator.serviceWorker?.addEventListener('controllerchange',()=>checkOffline());
function connection(){const b=$('#connection-banner');b.hidden=navigator.onLine;b.textContent='You’re offline. Your catalogue and saved list are available; external services will need a connection.'}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
$('#detail-dialog').addEventListener('close',stopCamera);
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='supplier')supplierDetail(id);if(a==='standards')standardsDialog();if(a==='about')aboutDialog();if(a==='location')locationDialog();if(a==='geolocate')geolocate();if(a==='clear-location'){state.origin=null;$('#location-label').textContent='Edinburgh';render()}if(a==='settings')settingsDialog();if(a==='install')install();if(a==='export')exportData();if(a==='basket-stores')basketStores();if(a==='camera')startCamera();if(a==='photo')$('#barcode-photo').click();if(a==='save-standards'){state.outdoor=$('#outdoor-toggle').checked;persist();$('#detail-dialog').close();render();toast('Your standards are saved')}if(['increase','decrease','remove'].includes(a)){if(a==='increase')state.basket[id]=Math.min(99,(state.basket[id]||0)+1);if(a==='decrease'){state.basket[id]--;if(state.basket[id]<=0)delete state.basket[id]}if(a==='remove')delete state.basket[id];persist();render()}if(a==='update-app'){swRegistration?.waiting?.postMessage({type:'SKIP_WAITING'});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true})}if(a==='reset-dialog')dialog('Clear your saved data?',`<p>This removes your Fieldfare basket, saved products and sourcing preference from this device. Export your list first if you want to keep it.</p>`,`<button class="btn" data-action="close">Keep my data</button><button class="btn danger" data-action="reset-confirm">Clear my data</button>`);if(a==='reset-confirm'){state.basket={};state.saved=[];state.outdoor=true;persist();$('#detail-dialog').close();render();toast('Saved data cleared')}});
document.addEventListener('change',e=>{if(e.target.id==='barcode-photo')scanPhoto(e.target.files[0])});
window.addEventListener('pagehide',stopCamera);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_meat_catalogue',title:'Search Fieldfare products',description:'Search researched meat candidates. Results are not automatic welfare approvals or live stock.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(typeof input?.query!=='string'||input.query.length>200)throw new Error('Provide a query of up to 200 characters');return products.filter(p=>`${p.name} ${p.retailer} ${p.species}`.toLowerCase().includes(input.query.toLowerCase())).map(p=>({id:p.id,name:p.name,supplier:p.retailer,source:p.url,status:'sourcing_candidate'}))}},{name:'add_products_to_shopping_list',title:'Add products to Fieldfare list',description:'Add known product IDs to the device-local shopping list. Does not place an order.',inputSchema:{type:'object',properties:{productIds:{type:'array',items:{type:'string'},minItems:1,maxItems:20}},required:['productIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Array.isArray(input?.productIds)||!input.productIds.length||input.productIds.length>20||input.productIds.some(id=>typeof id!=='string'||!products.some(p=>p.id===id)))throw new Error('Use 1–20 valid catalogue product IDs');input.productIds.forEach(add);state.route='basket';if(location.hash!=='#basket')location.hash='basket';render();return {added:input.productIds,totalItems:count(),ordered:false}}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
render();registerTools();
